//! Mesh administration (design §7.9, revised): kiosk-style unlocking with **insider-resistant**
//! authority.
//!
//! The admin secret (128-bit, generated by the app, exportable to other phones and the
//! bridge) never reaches a fixture. The app derives a P-256 **admin signing key** from it;
//! members hold only the **admin public key**. A member can therefore verify admin authority
//! but never create it, and holding the shared mesh key gives no power to command.
//!
//! 1. **Session grant.** To administer through gateway G (any fixture the app or bridge is
//!    connected to), the app signs a [`Grant`]: "G (its device key) may issue commands for
//!    session S until T". Presenting a valid grant is `mesh_unlock` ([`AdminGate`]; a bad one
//!    locks unlocking out for 2 s, as kiosk). G broadcasts the grant; each member verifies
//!    its signature **once per session** and derives a pairwise key with G (ECDH of the two
//!    device keys).
//! 2. **Freshness, not time.** Each member answers the grant with [`SessionMsg::Ack`]
//!    (its device key, a fresh nonce, a MAC under the pairwise key that proves it holds that
//!    key); G replies [`SessionMsg::Confirm`] with its current 64-bit frame counter bound to
//!    that nonce. From then on the member accepts only command sequences above what it last
//!    accepted and no more than [`FRESH_WINDOW`] below the confirmed counter. A member with no
//!    session (fresh join, reboot) holds G's commands and asks for the grant first: a
//!    replayed command from before can never be accepted, however long ago it was captured.
//! 3. **Per-receiver MACs.** Each admin-class packet G originates carries, per recipient, a
//!    6-byte MAC under that recipient's pairwise key with G ([`seal_command`]). No other
//!    member holds those keys, so no other member can forge, alter or redirect a command.
//!    Cost: 13 bytes + 8 per recipient (61 bytes for 6 fixtures; a packet carries at most
//!    `(payload - 13 - body) / 8` recipients, ~20 at 200 B, so a larger target set takes
//!    several packets).
//!
//! What a compromised member can still do: relay or drop, send group-key data traffic under
//! any source id (status, replies: not security-relevant), and command through a grant only
//! if the admin granted it a session.

use crate::backhaul::NodeId;
use crate::crypto::{ct_eq, hmac, key_hash, p256_verify_parts, pairwise_key, DeviceKey, Entropy, KeyHash, PublicKey};
use crate::codec::{R, W};

pub const ADMIN_SECRET_LEN: usize = 16;
/// A wrong grant locks unlocking out this long (kiosk's `UNLOCK_LOCKOUT_MS`).
pub const UNLOCK_LOCKOUT_US: i64 = 2_000_000;
/// Connections a gateway tracks (wss slots + BLE).
pub const MAX_CONNECTIONS: usize = 8;
/// Per-recipient command MAC: 2-byte node id + 6-byte MAC.
pub const MAC_LEN: usize = 6;
pub const ENTRY_LEN: usize = 2 + MAC_LEN;
/// session (4) ‖ seq (8) ‖ recipient count (1).
pub const COMMAND_HEADER: usize = 13;
/// A held (pre-sync) command is accepted if its sequence is at most this far below the
/// gateway's confirmed counter. The member asks for the grant the moment it holds a command,
/// so a genuine one is a few frames old; 64 of the gateway's frames is ~1 s while it streams
/// control and up to ~30 s when idle (beacons and adverts only). A replay inside that window
/// right after a reboot is the residual (design §7.5).
pub const FRESH_WINDOW: u64 = 64;
/// Sessions a member keeps (two admins on two gateways at once).
pub const SESSIONS: usize = 2;
/// A member re-sends its Ack this often until confirmed.
pub const ACK_RETRY_US: i64 = 1_000_000;
/// The longest admin grant a gateway accepts, from its own mesh time (desk D-328: 12 h, the
/// app renews in the background in M8; 5 min of slack for the app's view of mesh time).
pub const MAX_GRANT_S: u32 = 12 * 3600 + 300;

/// "Gateway G may issue commands for session S until T", signed by the admin key.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Grant {
    pub mesh_id: u32,
    pub session: u32,
    pub gateway: NodeId,
    pub gateway_key: PublicKey,
    /// Expiry in mesh seconds (§6; until M4, the gateway's notion of time).
    pub not_after: u32,
    pub sig: [u8; 64],
}

impl Grant {
    pub const LEN: usize = 1 + 4 + 4 + 2 + 65 + 4 + 64;

    /// The signed bytes, as parts.
    pub fn signed<'a>(&self, buf: &'a mut [u8; 87]) -> &'a [u8] {
        let mut w = W::new(buf);
        w.put(b"SMgrant1").u32(self.mesh_id).u32(self.session).u16(self.gateway).put(&self.gateway_key);
        let n = w.u32(self.not_after).done().unwrap_or(0);
        &buf[..n]
    }

    pub fn verify(&self, admin_key: &PublicKey) -> bool {
        let mut b = [0u8; 87];
        let m = self.signed(&mut b);
        p256_verify_parts(admin_key, &[m], &self.sig)
    }

    fn encode_into(&self, w: &mut W<'_>) {
        w.u8(T_GRANT).u32(self.mesh_id).u32(self.session).u16(self.gateway).put(&self.gateway_key).u32(self.not_after).put(&self.sig);
    }

    fn decode_from(r: &mut R<'_>) -> Option<Grant> {
        Some(Grant { mesh_id: r.u32()?, session: r.u32()?, gateway: r.u16()?, gateway_key: r.arr()?, not_after: r.u32()?, sig: r.arr()? })
    }
}

pub const T_GRANT: u8 = 0x40;
pub const T_ACK: u8 = 0x41;
pub const T_CONFIRM: u8 = 0x42;
pub const T_REQUEST: u8 = 0x43;

/// Session and freshness messages (the `FRESHNESS` port; authenticated by signature or
/// pairwise MAC, not by the shared key).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SessionMsg {
    Grant(Grant),
    /// Member → gateway: my device key, a nonce, MAC(pairwise, session ‖ node ‖ nonce).
    Ack { session: u32, node: NodeId, key: PublicKey, nonce: u64, mac: [u8; 8] },
    /// Gateway → member: my counter now, bound to your nonce.
    Confirm { session: u32, node: NodeId, nonce: u64, counter: u64, mac: [u8; 8] },
    /// Member → gateway: send me the grant for this session (I hold none).
    Request { session: u32, node: NodeId },
}

impl SessionMsg {
    pub fn encode(&self, out: &mut [u8]) -> Option<usize> {
        let mut w = W::new(out);
        match self {
            SessionMsg::Grant(g) => g.encode_into(&mut w),
            SessionMsg::Ack { session, node, key, nonce, mac } => {
                w.u8(T_ACK).u32(*session).u16(*node).put(key).put(&nonce.to_be_bytes()).put(mac);
            }
            SessionMsg::Confirm { session, node, nonce, counter, mac } => {
                w.u8(T_CONFIRM).u32(*session).u16(*node).put(&nonce.to_be_bytes()).put(&counter.to_be_bytes()).put(mac);
            }
            SessionMsg::Request { session, node } => {
                w.u8(T_REQUEST).u32(*session).u16(*node);
            }
        }
        w.done()
    }

    pub fn decode(b: &[u8]) -> Option<SessionMsg> {
        let mut r = R::new(b);
        let m = match r.u8()? {
            T_GRANT => SessionMsg::Grant(Grant::decode_from(&mut r)?),
            T_ACK => SessionMsg::Ack {
                session: r.u32()?,
                node: r.u16()?,
                key: r.arr()?,
                nonce: u64::from_be_bytes(r.arr()?),
                mac: r.arr()?,
            },
            T_CONFIRM => SessionMsg::Confirm {
                session: r.u32()?,
                node: r.u16()?,
                nonce: u64::from_be_bytes(r.arr()?),
                counter: u64::from_be_bytes(r.arr()?),
                mac: r.arr()?,
            },
            T_REQUEST => SessionMsg::Request { session: r.u32()?, node: r.u16()? },
            _ => return None,
        };
        r.end()?;
        Some(m)
    }
}

fn mac8(k: &[u8; 16], parts: &[&[u8]]) -> [u8; 8] {
    let h = hmac(k, parts);
    let mut m = [0u8; 8];
    m.copy_from_slice(&h[..8]);
    m
}

pub fn ack_mac(k: &[u8; 16], session: u32, node: NodeId, nonce: u64) -> [u8; 8] {
    mac8(k, &[b"SMack1", &session.to_be_bytes(), &node.to_be_bytes(), &nonce.to_be_bytes()])
}

pub fn confirm_mac(k: &[u8; 16], session: u32, node: NodeId, nonce: u64, counter: u64) -> [u8; 8] {
    mac8(k, &[b"SMconf1", &session.to_be_bytes(), &node.to_be_bytes(), &nonce.to_be_bytes(), &counter.to_be_bytes()])
}

/// One recipient's command MAC.
pub fn command_mac(k: &[u8; 16], mesh_id: u32, session: u32, seq: u64, port: u8, body: &[u8]) -> [u8; MAC_LEN] {
    let h = hmac(k, &[b"SMcmd1", &mesh_id.to_be_bytes(), &session.to_be_bytes(), &seq.to_be_bytes(), &[port], body]);
    let mut m = [0u8; MAC_LEN];
    m.copy_from_slice(&h[..MAC_LEN]);
    m
}

/// How many recipients fit one packet of `max_payload` bytes with a `body`-byte body.
pub const fn recipients_per_packet(max_payload: usize, body: usize) -> usize {
    max_payload.saturating_sub(COMMAND_HEADER + body) / ENTRY_LEN
}

/// Frame a command: `session ‖ seq ‖ n ‖ [node ‖ MAC] × n ‖ body`.
pub fn seal_command(
    mesh_id: u32,
    session: u32,
    seq: u64,
    port: u8,
    body: &[u8],
    recipients: &[(NodeId, [u8; 16])],
    out: &mut [u8],
) -> Option<usize> {
    if recipients.len() > u8::MAX as usize {
        return None;
    }
    let mut w = W::new(out);
    w.u32(session).put(&seq.to_be_bytes()).u8(recipients.len() as u8);
    for (node, k) in recipients {
        w.u16(*node).put(&command_mac(k, mesh_id, session, seq, port, body));
    }
    w.put(body).done()
}

/// A parsed command.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Command<'a> {
    pub session: u32,
    pub seq: u64,
    entries: &'a [u8],
    pub body: &'a [u8],
}

impl<'a> Command<'a> {
    pub fn parse(p: &'a [u8]) -> Option<Command<'a>> {
        let mut r = R::new(p);
        let session = r.u32()?;
        let seq = u64::from_be_bytes(r.arr()?);
        let n = r.u8()? as usize;
        let entries = r.take(n * ENTRY_LEN)?;
        Some(Command { session, seq, entries, body: r.rest() })
    }

    pub fn recipients(&self) -> impl Iterator<Item = NodeId> + '_ {
        self.entries.chunks(ENTRY_LEN).map(|e| u16::from_be_bytes([e[0], e[1]]))
    }

    /// Is this command for `me`, with a valid MAC under `k`?
    pub fn verify(&self, k: &[u8; 16], mesh_id: u32, port: u8, me: NodeId) -> Option<bool> {
        let e = self.entries.chunks(ENTRY_LEN).find(|e| u16::from_be_bytes([e[0], e[1]]) == me)?;
        Some(ct_eq(&command_mac(k, mesh_id, self.session, self.seq, port, self.body), &e[2..]))
    }
}

/// A member's view of one admin session.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct MemberSession {
    pub session: u32,
    pub gateway: NodeId,
    pub gateway_hash: KeyHash,
    pub key: [u8; 16],
    pub not_after: u32,
    nonce: u64,
    /// The gateway counter its Confirm vouched for (None: not synced yet).
    pub floor: Option<u64>,
    last_seq: u64,
    ack_us: i64,
    tries: u8,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum GrantReject {
    WrongMesh,
    /// The admin key did not sign it (or this member has no admin key).
    BadSignature,
    Expired,
    /// ECDH with the gateway's key failed.
    BadKey,
}

/// What a member does with a command.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Verdict {
    Accept,
    /// Not for this member (no MAC entry for it).
    NotForMe,
    /// No session or not yet synced: hold it, ask the gateway (the stack sends the Ack or
    /// Request), decide once synced.
    Hold { session: u32 },
    Reject(CommandReject),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CommandReject {
    BadMac,
    /// A sequence already used, or older than the confirmed counter's window.
    Stale,
    Expired,
    /// From a node that is not the session's gateway.
    WrongOrigin,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct SessionStats {
    pub grants_verified: u32,
    /// Grants that only extended an existing session's expiry.
    pub renewals: u32,
    pub grants_rejected: u32,
    pub confirms: u32,
    pub bad_confirms: u32,
    pub accepted: u32,
    pub held: u32,
    pub bad_mac: u32,
    pub stale: u32,
    pub not_for_me: u32,
}

/// A member's admin sessions.
pub struct Sessions {
    s: [Option<MemberSession>; SESSIONS],
    pub stats: SessionStats,
}

impl Default for Sessions {
    fn default() -> Self {
        Self::new()
    }
}

impl Sessions {
    pub const fn new() -> Sessions {
        Sessions {
            s: [None; SESSIONS],
            stats: SessionStats {
                grants_verified: 0,
                renewals: 0,
                grants_rejected: 0,
                confirms: 0,
                bad_confirms: 0,
                accepted: 0,
                held: 0,
                bad_mac: 0,
                stale: 0,
                not_for_me: 0,
            },
        }
    }

    /// Whether `g` needs the expensive path (a signature verify, maybe an ECDH): a session
    /// we don't hold, or a renewal of one we do. Cheap to ask; the stack queues the rest for
    /// its low-priority crypto task.
    pub fn needs_crypto(&self, g: &Grant) -> bool {
        match self.s.iter().flatten().find(|s| s.session == g.session && s.gateway == g.gateway) {
            Some(s) => g.not_after > s.not_after,
            None => true,
        }
    }

    /// Sessions whose gateway confirmed our freshness (their commands are accepted).
    pub fn synced(&self) -> usize {
        self.s.iter().flatten().filter(|s| s.floor.is_some()).count()
    }

    pub fn get(&self, session: u32) -> Option<&MemberSession> {
        self.s.iter().flatten().find(|s| s.session == session)
    }

    /// A grant heard: verify it once (ECDSA), derive the pairwise key (ECDH), and return
    /// the Ack to send. A grant already held is not re-verified; its Ack is re-sent only if
    /// still unconfirmed.
    #[allow(clippy::too_many_arguments)]
    pub fn on_grant(
        &mut self,
        now_us: i64,
        mesh_time_s: u32,
        g: &Grant,
        admin_key: Option<&PublicKey>,
        mesh_id: u32,
        me: NodeId,
        dev: &dyn DeviceKey,
        rng: &mut dyn Entropy,
    ) -> Result<Option<SessionMsg>, GrantReject> {
        if g.mesh_id != mesh_id {
            return Err(GrantReject::WrongMesh);
        }
        if let Some(s) = self.s.iter_mut().flatten().find(|s| s.session == g.session && s.gateway == g.gateway) {
            // A renewal: the same session with a later expiry. One signature check, no new
            // keys, roster or acks (design §7.9, "when crypto cost is paid").
            if g.not_after > s.not_after {
                if !admin_key.is_some_and(|k| g.verify(k)) {
                    self.stats.grants_rejected += 1;
                    return Err(GrantReject::BadSignature);
                }
                s.not_after = g.not_after;
                self.stats.renewals += 1;
            }
            if s.floor.is_some() || now_us - s.ack_us < ACK_RETRY_US {
                return Ok(None);
            }
            s.ack_us = now_us;
            let s = *s;
            return Ok(Some(SessionMsg::Ack { session: s.session, node: me, key: dev.public_key(), nonce: s.nonce, mac: ack_mac(&s.key, s.session, me, s.nonce) }));
        }
        if g.not_after < mesh_time_s {
            self.stats.grants_rejected += 1;
            return Err(GrantReject::Expired);
        }
        if !admin_key.is_some_and(|k| g.verify(k)) {
            self.stats.grants_rejected += 1;
            return Err(GrantReject::BadSignature);
        }
        let key = pairwise_key(dev, &g.gateway_key, mesh_id, me, g.gateway).ok_or(GrantReject::BadKey)?;
        self.stats.grants_verified += 1;
        let mut nb = [0u8; 8];
        rng.fill(&mut nb);
        let nonce = u64::from_be_bytes(nb);
        let s = MemberSession {
            session: g.session,
            gateway: g.gateway,
            gateway_hash: key_hash(&g.gateway_key),
            key,
            not_after: g.not_after,
            nonce,
            floor: None,
            last_seq: 0,
            ack_us: now_us,
            tries: 0,
        };
        // Replace an empty slot, else the session expiring first.
        let i = self.s.iter().position(|x| x.is_none()).unwrap_or_else(|| (0..SESSIONS).min_by_key(|&i| self.s[i].map_or(0, |s| s.not_after)).unwrap_or(0));
        self.s[i] = Some(s);
        Ok(Some(SessionMsg::Ack { session: s.session, node: me, key: dev.public_key(), nonce, mac: ack_mac(&key, s.session, me, nonce) }))
    }

    /// A Confirm for us: the gateway's counter, if it verifies.
    pub fn on_confirm(&mut self, from: NodeId, m: &SessionMsg, me: NodeId) -> Option<(NodeId, u64)> {
        let SessionMsg::Confirm { session, node, nonce, counter, mac } = *m else { return None };
        if node != me {
            return None;
        }
        let s = self.s.iter_mut().flatten().find(|s| s.session == session && s.gateway == from)?;
        if nonce != s.nonce || !ct_eq(&confirm_mac(&s.key, session, me, nonce, counter), &mac) {
            self.stats.bad_confirms += 1;
            return None;
        }
        self.stats.confirms += 1;
        s.floor = Some(s.floor.map_or(counter, |f| f.max(counter)));
        Some((s.gateway, counter))
    }

    /// Unconfirmed sessions whose Ack is due again: 1, 2, then every 4 s, with per-node
    /// jitter (64 members answering one grant must not retry in step).
    pub fn due_ack(&mut self, now_us: i64, me: NodeId, dev: &dyn DeviceKey) -> Option<(NodeId, SessionMsg)> {
        let s = self.s.iter_mut().flatten().find(|s| {
            let wait = (ACK_RETRY_US << s.tries.min(2)) + (s.nonce % 500_000) as i64;
            s.floor.is_none() && now_us - s.ack_us >= wait
        })?;
        s.ack_us = now_us;
        s.tries = s.tries.saturating_add(1);
        let s = *s;
        Some((s.gateway, SessionMsg::Ack { session: s.session, node: me, key: dev.public_key(), nonce: s.nonce, mac: ack_mac(&s.key, s.session, me, s.nonce) }))
    }

    /// Judge a command from `origin` on `port`.
    pub fn check(&mut self, c: &Command<'_>, origin: NodeId, port: u8, mesh_id: u32, me: NodeId, mesh_time_s: u32) -> Verdict {
        let v = self.judge(c, origin, port, mesh_id, me, mesh_time_s);
        let st = &mut self.stats;
        match v {
            Verdict::Accept => st.accepted += 1,
            Verdict::Hold { .. } => st.held += 1,
            Verdict::NotForMe => st.not_for_me += 1,
            Verdict::Reject(CommandReject::BadMac) => st.bad_mac += 1,
            Verdict::Reject(_) => st.stale += 1,
        }
        v
    }

    fn judge(&mut self, c: &Command<'_>, origin: NodeId, port: u8, mesh_id: u32, me: NodeId, mesh_time_s: u32) -> Verdict {
        if !c.recipients().any(|r| r == me) {
            return Verdict::NotForMe;
        }
        let Some(s) = self.s.iter_mut().flatten().find(|s| s.session == c.session) else {
            return Verdict::Hold { session: c.session };
        };
        if origin != s.gateway {
            return Verdict::Reject(CommandReject::WrongOrigin);
        }
        match c.verify(&s.key, mesh_id, port, me) {
            Some(true) => {}
            _ => return Verdict::Reject(CommandReject::BadMac),
        }
        if s.not_after < mesh_time_s {
            return Verdict::Reject(CommandReject::Expired);
        }
        let Some(floor) = s.floor else { return Verdict::Hold { session: c.session } };
        if c.seq <= s.last_seq || c.seq.saturating_add(FRESH_WINDOW) < floor {
            return Verdict::Reject(CommandReject::Stale);
        }
        s.last_seq = c.seq;
        Verdict::Accept
    }
}

/// One member in a gateway's session roster.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct RosterEntry {
    pub node: NodeId,
    pub key: [u8; 16],
    pub hash: KeyHash,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct RosterStats {
    pub acks: u32,
    pub bad_acks: u32,
    /// An Ack for a node id already bound to another device key (kept the first: trust on
    /// first use, as the app's device pinning; the app is told).
    pub key_conflicts: u32,
    pub full: u32,
}

/// A gateway's session: its grant and the members that acknowledged it, with their
/// pairwise keys (`N` entries: 16 on a standalone C6, 64+ where RAM allows).
pub struct GatewaySession<const N: usize> {
    pub grant: Grant,
    roster: [Option<RosterEntry>; N],
    pub stats: RosterStats,
}

impl<const N: usize> GatewaySession<N> {
    pub fn new(grant: Grant) -> Self {
        GatewaySession { grant, roster: [None; N], stats: RosterStats::default() }
    }

    /// A renewal of this session (same session and gateway key, later expiry): keep the
    /// roster and its pairwise keys.
    pub fn renew(&mut self, grant: Grant) -> bool {
        if grant.session == self.grant.session && grant.gateway_key == self.grant.gateway_key && grant.not_after > self.grant.not_after {
            self.grant = grant;
            true
        } else {
            false
        }
    }

    /// A member's Ack: check that it holds the key it claims (the MAC needs the pairwise
    /// key), add it to the roster, and return the Confirm carrying our counter.
    pub fn on_ack(&mut self, m: &SessionMsg, dev: &dyn DeviceKey, mesh_id: u32, me: NodeId, counter: u64) -> Option<(NodeId, SessionMsg)> {
        let SessionMsg::Ack { session, node, key, nonce, mac } = *m else { return None };
        if session != self.grant.session {
            return None;
        }
        let k = pairwise_key(dev, &key, mesh_id, me, node)?;
        if !ct_eq(&ack_mac(&k, session, node, nonce), &mac) {
            self.stats.bad_acks += 1;
            return None;
        }
        let hash = key_hash(&key);
        match self.roster.iter().flatten().find(|e| e.node == node) {
            Some(e) if e.hash != hash => {
                self.stats.key_conflicts += 1;
                return None;
            }
            Some(_) => {}
            None => match self.roster.iter().position(|e| e.is_none()) {
                Some(i) => self.roster[i] = Some(RosterEntry { node, key: k, hash }),
                None => {
                    self.stats.full += 1;
                    return None;
                }
            },
        }
        self.stats.acks += 1;
        Some((node, SessionMsg::Confirm { session, node, nonce, counter, mac: confirm_mac(&k, session, node, nonce, counter) }))
    }

    /// A member removed by a rotation (M7): no more per-receiver MACs for it.
    pub fn remove(&mut self, node: NodeId) {
        for e in self.roster.iter_mut() {
            if e.is_some_and(|e| e.node == node) {
                *e = None;
            }
        }
    }

    pub fn roster(&self) -> impl Iterator<Item = &RosterEntry> {
        self.roster.iter().flatten()
    }

    pub fn entry(&self, node: NodeId) -> Option<&RosterEntry> {
        self.roster().find(|e| e.node == node)
    }

    pub fn len(&self) -> usize {
        self.roster().count()
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum UnlockError {
    /// A bad grant was presented less than 2 s ago (device-wide).
    LockedOut,
    /// Not signed by the admin key, not for this gateway, or expired (starts the lockout).
    BadGrant,
    /// This device holds no admin public key.
    NoAdminKey,
    BadConnection,
}

/// The gateway's unlock state: which connections hold a valid grant, and the lockout.
#[derive(Clone, Copy, Debug, Default)]
pub struct AdminGate {
    unlocked: [Option<u32>; MAX_CONNECTIONS],
    lockout_until_us: Option<i64>,
}

impl AdminGate {
    pub const fn new() -> AdminGate {
        AdminGate { unlocked: [None; MAX_CONNECTIONS], lockout_until_us: None }
    }

    /// `mesh_unlock{grant}` on connection `conn`: the app signed a grant for this gateway.
    #[allow(clippy::too_many_arguments)]
    pub fn unlock(
        &mut self,
        now_us: i64,
        mesh_time_s: u32,
        conn: usize,
        g: &Grant,
        admin_key: Option<&PublicKey>,
        mesh_id: u32,
        me: NodeId,
        my_key: &PublicKey,
    ) -> Result<(), UnlockError> {
        if conn >= MAX_CONNECTIONS {
            return Err(UnlockError::BadConnection);
        }
        if let Some(until) = self.lockout_until_us {
            if now_us < until {
                return Err(UnlockError::LockedOut);
            }
            self.lockout_until_us = None;
        }
        let Some(ak) = admin_key else { return Err(UnlockError::NoAdminKey) };
        let ok = g.mesh_id == mesh_id && g.gateway == me && g.gateway_key == *my_key && g.not_after >= mesh_time_s
            && g.not_after - mesh_time_s <= MAX_GRANT_S
            && g.verify(ak);
        if !ok {
            self.lockout_until_us = Some(now_us + UNLOCK_LOCKOUT_US);
            return Err(UnlockError::BadGrant);
        }
        self.unlocked[conn] = Some(g.session);
        Ok(())
    }

    /// Envelope trust (a mesh with no admin key, mesh M5): connection `conn` holds the
    /// gateway's session without a grant ([`crate::ports::SESSION_ENVELOPE`]). The caller
    /// checks that no admin key is provisioned.
    pub fn open_envelope(&mut self, conn: usize) -> Result<(), UnlockError> {
        let u = self.unlocked.get_mut(conn).ok_or(UnlockError::BadConnection)?;
        *u = Some(crate::ports::SESSION_ENVELOPE);
        Ok(())
    }

    /// Any connection holds a session (this device is acting as a gateway).
    pub fn any(&self) -> bool {
        self.unlocked.iter().any(|u| u.is_some())
    }

    pub fn session(&self, conn: usize) -> Option<u32> {
        self.unlocked.get(conn).copied().flatten()
    }

    pub fn is_unlocked(&self, conn: usize) -> bool {
        self.session(conn).is_some()
    }

    /// A connection opened or dropped: it is never unlocked.
    pub fn connection_changed(&mut self, conn: usize) {
        if let Some(u) = self.unlocked.get_mut(conn) {
            *u = None;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::crypto::DeviceKey;
    use crate::host_keys::{AdminSigner, HostKey, TestRng};

    const MESH: u32 = 0xA1B2_C3D4;

    fn grant(signer: &AdminSigner, gw: &HostKey, session: u32, not_after: u32) -> Grant {
        signer.grant(MESH, session, 1, gw.public_key(), not_after)
    }

    /// The whole member/gateway exchange, and what an insider cannot do.
    #[test]
    fn grant_ack_confirm_then_commands_with_per_receiver_macs() {
        let admin = AdminSigner::from_secret(b"0123456789abcdef", MESH);
        let (gw, m2, m3) = (HostKey::from_seed(1), HostKey::from_seed(2), HostKey::from_seed(3));
        let mut rng = TestRng(5);
        let g = grant(&admin, &gw, 7, 1000);
        // The gateway unlocks its connection with the grant.
        let mut gate = AdminGate::new();
        assert_eq!(gate.unlock(0, 0, 0, &g, Some(&admin.public()), MESH, 1, &gw.public_key()), Ok(()));
        let forged = Grant { not_after: 99_999, ..g };
        assert_eq!(gate.unlock(0, 0, 1, &forged, Some(&admin.public()), MESH, 1, &gw.public_key()), Err(UnlockError::BadGrant));
        assert_eq!(gate.unlock(1_000_000, 0, 1, &g, Some(&admin.public()), MESH, 1, &gw.public_key()), Err(UnlockError::LockedOut));
        // Members verify once, ack, get confirmed.
        let mut gs = GatewaySession::<8>::new(g);
        let mut s2 = Sessions::new();
        let mut s3 = Sessions::new();
        for (s, dev, id) in [(&mut s2, &m2, 2u16), (&mut s3, &m3, 3)] {
            let ack = s.on_grant(0, 0, &g, Some(&admin.public()), MESH, id, dev, &mut rng).unwrap().unwrap();
            assert_eq!(s.on_grant(10, 0, &g, Some(&admin.public()), MESH, id, dev, &mut rng), Ok(None), "verified once");
            let (to, conf) = gs.on_ack(&ack, &gw, MESH, 1, 5_000).unwrap();
            assert_eq!(to, id);
            assert_eq!(s.on_confirm(1, &conf, id), Some((1, 5_000)));
        }
        assert_eq!(s2.stats.grants_verified, 1);
        // A command to both, MAC'd per receiver.
        let rec: Vec<_> = gs.roster().map(|e| (e.node, e.key)).collect();
        let mut buf = [0u8; 200];
        let n = seal_command(MESH, 7, 5_010, 16, b"set_uniforms", &rec, &mut buf).unwrap();
        assert_eq!(n, COMMAND_HEADER + 2 * ENTRY_LEN + 12);
        let c = Command::parse(&buf[..n]).unwrap();
        assert_eq!(s2.check(&c, 1, 16, MESH, 2, 0), Verdict::Accept);
        assert_eq!(s3.check(&c, 1, 16, MESH, 3, 0), Verdict::Accept);
        assert_eq!(s2.check(&c, 1, 16, MESH, 2, 0), Verdict::Reject(CommandReject::Stale), "once");
        // Insider: member 3 holds the mesh key and its own pairwise key with the gateway,
        // but not member 2's: anything it builds for member 2 fails.
        let k3 = s3.get(7).unwrap().key;
        let n = seal_command(MESH, 7, 6_000, 16, b"set_effect evil", &[(2, k3), (3, k3)], &mut buf).unwrap();
        let c = Command::parse(&buf[..n]).unwrap();
        assert_eq!(s2.check(&c, 1, 16, MESH, 2, 0), Verdict::Reject(CommandReject::BadMac));
        // Altering a real command's body breaks every MAC.
        let n = seal_command(MESH, 7, 5_020, 16, b"set_effect a", &rec, &mut buf).unwrap();
        buf[n - 1] ^= 1;
        assert_eq!(s2.check(&Command::parse(&buf[..n]).unwrap(), 1, 16, MESH, 2, 0), Verdict::Reject(CommandReject::BadMac));
        // A member without a session holds and asks.
        let mut s4 = Sessions::new();
        let n = seal_command(MESH, 7, 5_030, 16, b"x", &[(4, [0; 16])], &mut buf).unwrap();
        assert_eq!(s4.check(&Command::parse(&buf[..n]).unwrap(), 1, 16, MESH, 4, 0), Verdict::Hold { session: 7 });
        // Expired grants are refused.
        assert_eq!(s4.on_grant(0, 2000, &g, Some(&admin.public()), MESH, 4, &m2, &mut rng), Err(GrantReject::Expired));
        // A grant not signed by the admin key.
        let rogue = AdminSigner::from_secret(b"fedcba9876543210", MESH).grant(MESH, 8, 1, gw.public_key(), 1000);
        assert_eq!(s4.on_grant(0, 0, &rogue, Some(&admin.public()), MESH, 4, &m2, &mut rng), Err(GrantReject::BadSignature));
    }

    /// After a reboot (no session state), an old command captured off the air is refused:
    /// the fresh Confirm's counter is far past it. A command sent just before the sync is
    /// still accepted.
    #[test]
    fn freshness_after_a_reboot_refuses_old_commands() {
        let admin = AdminSigner::from_secret(b"0123456789abcdef", MESH);
        let (gw, m2) = (HostKey::from_seed(1), HostKey::from_seed(2));
        let mut rng = TestRng(9);
        let g = grant(&admin, &gw, 7, 1000);
        let mut gs = GatewaySession::<4>::new(g);
        let mut s = Sessions::new();
        let ack = s.on_grant(0, 0, &g, Some(&admin.public()), MESH, 2, &m2, &mut rng).unwrap().unwrap();
        let (_, conf) = gs.on_ack(&ack, &gw, MESH, 1, 100).unwrap();
        s.on_confirm(1, &conf, 2);
        let k = gs.entry(2).unwrap().key;
        let mut old = [0u8; 64];
        let n_old = seal_command(MESH, 7, 150, 16, b"old", &[(2, k)], &mut old).unwrap();
        assert_eq!(s.check(&Command::parse(&old[..n_old]).unwrap(), 1, 16, MESH, 2, 0), Verdict::Accept);
        // Reboot. Much later the gateway's counter is at 100_000.
        let mut s = Sessions::new();
        let c_old = Command::parse(&old[..n_old]).unwrap();
        assert_eq!(s.check(&c_old, 1, 16, MESH, 2, 0), Verdict::Hold { session: 7 });
        let mut recent = [0u8; 64];
        let n_recent = seal_command(MESH, 7, 99_990, 16, b"recent", &[(2, k)], &mut recent).unwrap(); // 10 frames before the sync
        let ack = s.on_grant(0, 0, &g, Some(&admin.public()), MESH, 2, &m2, &mut rng).unwrap().unwrap();
        let (_, conf) = gs.on_ack(&ack, &gw, MESH, 1, 100_000).unwrap();
        assert_eq!(s.on_confirm(1, &conf, 2), Some((1, 100_000)));
        assert_eq!(s.check(&c_old, 1, 16, MESH, 2, 0), Verdict::Reject(CommandReject::Stale));
        assert_eq!(s.check(&Command::parse(&recent[..n_recent]).unwrap(), 1, 16, MESH, 2, 0), Verdict::Accept);
        // A Confirm replayed from the old session (other nonce) does nothing.
        assert_eq!(s.on_confirm(1, &conf, 2), Some((1, 100_000)));
        let SessionMsg::Confirm { session, node, counter, mac, .. } = conf else { unreachable!() };
        let stale = SessionMsg::Confirm { session, node, nonce: 1, counter, mac };
        assert_eq!(s.on_confirm(1, &stale, 2), None);
    }

    #[test]
    fn roster_binds_node_to_key_and_refuses_impostors() {
        let admin = AdminSigner::from_secret(b"0123456789abcdef", MESH);
        let gw = HostKey::from_seed(1);
        let g = grant(&admin, &gw, 7, 1000);
        let mut gs = GatewaySession::<4>::new(g);
        let mut rng = TestRng(1);
        let mut s = Sessions::new();
        let ack = s.on_grant(0, 0, &g, Some(&admin.public()), MESH, 2, &HostKey::from_seed(2), &mut rng).unwrap().unwrap();
        assert!(gs.on_ack(&ack, &gw, MESH, 1, 0).is_some());
        // Another device claiming node 2.
        let mut s_evil = Sessions::new();
        let evil = s_evil.on_grant(0, 0, &g, Some(&admin.public()), MESH, 2, &HostKey::from_seed(66), &mut rng).unwrap().unwrap();
        assert!(gs.on_ack(&evil, &gw, MESH, 1, 0).is_none());
        assert_eq!(gs.stats.key_conflicts, 1);
        // An Ack whose MAC was not made with the claimed key.
        let SessionMsg::Ack { session, nonce, mac, .. } = ack else { unreachable!() };
        let swapped = SessionMsg::Ack { session, node: 3, key: HostKey::from_seed(3).public_key(), nonce, mac };
        assert!(gs.on_ack(&swapped, &gw, MESH, 1, 0).is_none());
        assert_eq!(gs.stats.bad_acks, 1);
    }

    #[test]
    fn wire_roundtrips_and_sizes() {
        let admin = AdminSigner::from_secret(b"0123456789abcdef", MESH);
        let g = grant(&admin, &HostKey::from_seed(1), 7, 1000);
        let mut b = [0u8; 200];
        for (m, len) in [
            (SessionMsg::Grant(g), Grant::LEN),
            (SessionMsg::Ack { session: 1, node: 2, key: [4; 65], nonce: 3, mac: [5; 8] }, 88),
            (SessionMsg::Confirm { session: 1, node: 2, nonce: 3, counter: 4, mac: [5; 8] }, 31),
            (SessionMsg::Request { session: 1, node: 2 }, 7),
        ] {
            let n = m.encode(&mut b).unwrap();
            assert_eq!(n, len);
            assert_eq!(SessionMsg::decode(&b[..n]), Some(m));
            assert_eq!(SessionMsg::decode(&b[..n - 1]), None);
        }
        assert_eq!(recipients_per_packet(192, 20), 19);
        assert_eq!(recipients_per_packet(192, 150), 3);
    }
    /// D-328: a gateway takes grants of at most 12 h (plus slack) from its own mesh time.
    #[test]
    fn gateway_refuses_grants_longer_than_12_hours() {
        let admin = AdminSigner::from_secret(b"0123456789abcdef", MESH);
        let gw = HostKey::from_seed(1);
        let now_s = 5_000;
        let mut gate = AdminGate::new();
        let long = grant(&admin, &gw, 7, now_s + MAX_GRANT_S + 1);
        assert_eq!(gate.unlock(0, now_s, 0, &long, Some(&admin.public()), MESH, 1, &gw.public_key()), Err(UnlockError::BadGrant));
        let ok = grant(&admin, &gw, 7, now_s + 12 * 3600);
        assert_eq!(gate.unlock(3_000_000, now_s, 0, &ok, Some(&admin.public()), MESH, 1, &gw.public_key()), Ok(()));
    }
}
